import{_ as i,l as r,o as e,c as n,v as t,p as l,x as s,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"软更新对照","description":"","frontmatter":{"title":"软更新对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/soft-updates.md","filePath":"cs/soft-updates.md","lastUpdated":1789023840000}'),h={name:"cs/soft-updates.md"};function f(u,a,E,B,m,_){const o=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="软更新对照" tabindex="-1">软更新对照 <a class="header-anchor" href="#软更新对照" aria-label="Permalink to &quot;软更新对照&quot;">​</a></h1><div class="epigraph"><p>软更新不写日志：它在内存里给缓冲更新排依赖，使落盘顺序永远保持「先指针后对象」或反过来的安全方向，崩溃后至多泄漏，不交叉指错。</p><footer>—— 据 Ganger, McKusick, Patt et al., Soft Updates: A Technique for Eliminating Most Synchronous Writes in the Fast Filesystem, ACM TOCS 2002</footer></div><p><a href="/cs/fs-snapshots">上一课</a>把一致切面交给 COW 根。<a href="/cs/ext4-journal">日志</a> 把更新抄到旁路。<a href="/cs/log-structured-fs">LFS</a> 把盘当成日志。FFS 还可以走第三条路：<strong>软更新</strong>。本课是对照，不是劝你在 Linux 上启用它——Linux 主线走的是日志与 COW。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无序写回时，目录项可能指向未初始化的 inode，或位图显示空闲但文件仍指向该块——fsck 必须修交叉。若每次元数据都同步，性能崩。<a href="/cs/fsync">fsync</a> 只等待一个文件。缺口：给脏缓冲加依赖边（「这块必须先于那块」），循环依赖则先回滚内存里的部分更新、写盘、再重新挂上。崩溃后文件系统总是一种可挂载的超集：可能有未回收的 inode/块，没有「已用对象指向垃圾」。</p><p><span class="marginnote">McKusick 在 BSD FFS 落地。依赖图的结点是缓冲，不是 POSIX 操作。与数据库 WAL 对照：这里没有 REDO 记录，只有写序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>creat</code>：先保证 inode 在盘上已分配且链接计数正确，再写目录项。<code>unlink</code>：先清目录项，再把 inode 计数与块释放排在后面。写回守护进程只选取依赖已满足的缓冲。与 JBD2：没有 journal inode，没有 commit 块；恢复靠后台 <code>fsck -p</code> 回收泄漏，通常很快，因为结构不坏。</p>',8)),(e(),l(p,null,{default:s(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22creat%2Funlink%22%5D%20--%3E%20DEP%5B%22%E7%BC%93%E5%86%B2%E4%BE%9D%E8%B5%96%E8%BE%B9%22%5D%0A%20%20DEP%20--%3E%20WB%5B%22%E5%8F%AA%E5%86%99%E5%B0%B1%E7%BB%AA%E7%BC%93%E5%86%B2%22%5D%0A%20%20CRASH%5B%22%E5%B4%A9%E6%BA%83%22%5D%20--%3E%20LEAK%5B%22%E8%87%B3%E5%A4%9A%E6%B3%84%E6%BC%8F%22%5D%0A%20%20LEAK%20--%3E%20FSCK%5B%22%E5%90%8E%E5%8F%B0%E5%9B%9E%E6%94%B6%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>软更新把「崩溃一致」定义成<strong>永不指向未初始化对象</strong>，把泄漏交给 fsck。这比全量扫描修交叉便宜，又比重做一份日志少一次写。它不给快照当原语，也不给端到端校验当提交点。教学价值：同一 POSIX 树，至少三种实现——日志、COW、依赖序。</p><p>不要把软更新写成编译课的指令调度：虽然都是依赖图，对象是磁盘缓冲。</p><p>实现上：循环依赖时要 rollback 内存中的指针再写盘，等于短暂违背「内存即真相」。BSD 的后台 fsck 专门回收泄漏，所以软更新把正确性定义成「可挂载超集」而不是「无泄漏」。 读法上只引用<a href="/cs/fs-snapshots">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>软更新对照</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 BSD 与 Linux 的缓冲层代码对译。不保证 USB 拔出时依赖都已满足。下一课把「泄漏与交叉」收成工具：fsck 实际扫什么、日志/COW 之后它还剩什么工作。</p><p>版本字段会变，课序钉的是机制对象「软更新对照」，不是某一主线内核的结构体名。 后课默认：原地 FS 可以用依赖序避免交叉。检查与修复程序如何走超级块、位图与目录，下一课 fsck。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>软更新用写序保证不交叉；崩溃至多泄漏。</li><li>对照日志与 COW：旁路抄写 vs 新根 vs 依赖图。</li><li>fsck 的剩余工作是下一课。</li><li>出处：Ganger, McKusick, Patt et al., TOCS 2002；McKusick, <em>The Design and Implementation of the FreeBSD Operating System</em>。</li></ul>',11))])}const A=i(h,[["render",f]]);export{k as __pageData,A as default};
